import openpyxl

wb = openpyxl.load_workbook('/app/spreadsheets/1_22-47_input.xlsx')
ws = wb.active

# Extract source data from columns A:C
source_data = []
for i, row in enumerate(ws.iter_rows(min_row=1, values_only=True), 1):
    # Column A = index 0, B = index 1, C = index 2
    item = row[0]
    name = row[1]
    ref = row[2]

    # Skip empty cells
    if not name or not ref:
        continue

    # Skip headers
    if str(name).upper() == 'NAME' and str(item).upper() == 'ITEM':
        continue

    source_data.append({'row': i, 'item': item, 'name': name, 'ref': ref})

print("Source data rows:")
for d in source_data:
    print(f"  Row {d['row']}: {d['name']}, {d['ref']}")

# Get helper list from column J (skip header and empty)
helper_list = []
for i, row in enumerate(ws.iter_rows(min_row=1, values_only=True), 1):
    j_val = row[9]  # Column J
    if j_val and str(j_val).upper() != 'LIST':
        helper_list.append(str(j_val).strip().upper())

print(f"\nHelper list from J: {helper_list}")

# Identify and skip duplicates (same B AND C)
seen = set()
unique_data = []
for d in source_data:
    key = (str(d['name']).upper(), d['ref'])
    if key not in seen:
        seen.add(key)
        unique_data.append(d)

print(f"\nUnique data (skipping duplicates):")
for d in unique_data:
    print(f"  {d['name']}, {d['ref']}")

# Sort based on helper list
if helper_list:
    def sort_key(d):
        name_upper = str(d['name']).strip().upper()
        if name_upper in helper_list:
            return (0, helper_list.index(name_upper))
        else:
            return (1, unique_data.index(d))  # Keep original order
else:
    def sort_key(d):
        return (0, str(d['name']).strip().upper())  # Sort alphabetically A-Z

sorted_data = sorted(unique_data, key=sort_key)
print(f"\nSorted data:")
for d in sorted_data:
    print(f"  {d['name']}, {d['ref']}")
EOF

